'use strict';

var wald = require( './../lib' );

/*
* The Wald (inverse Gaussian) distribution is parameterized by mean `mu` and shape parameter `lambda`.
*/

var mu = 20.0;
var lambda = 60.0;

// Compute the mean:
console.log( 'Mean: %d', wald.mean( mu, lambda ) );

// Compute the mode:
console.log( 'Mode: %d', wald.mode( mu, lambda ) );

// Compute the variance:
console.log( 'Variance: %d', wald.variance( mu, lambda ) );

// Compute the standard deviation:
console.log( 'Standard Deviation: %d', wald.stdev( mu, lambda ) );

// Compute the skewness:
console.log( 'Skewness: %d', wald.skewness( mu, lambda ) );

// Compute the excess kurtosis:
console.log( 'Excess Kurtosis: %d', wald.kurtosis( mu, lambda ) );

// Evaluate the PDF at x = 20.0:
console.log( 'f(20.0): %d', wald.pdf( 20.0, mu, lambda ) );

// Evaluate the CDF at x = 20.0:
console.log( 'F(20.0): %d', wald.cdf( 20.0, mu, lambda ) );

// Evaluate the logPDF at x = 20.0:
console.log( 'ln(f(20.0)): %d', wald.logpdf( 20.0, mu, lambda ) );

// Evaluate the logCDF at x = 20.0:
console.log( 'ln(F(20.0)): %d', wald.logcdf( 20.0, mu, lambda ) );

// Compute the 50th percentile:
console.log( '50th Percentile: %d', wald.quantile( 0.5, mu, lambda ) );

// Evaluate the MGF at t = 0.01:
console.log( 'MGF(0.01): %d', wald.mgf( 0.01, mu, lambda ) );
